StructuredTextModel.Text:
(*
  GET ALPHA FUNCTION
  Returns upstream loss factor for given fluid
  Author: AhmadMohammad | Date: 2025-11-05
  α is in bar·min² / L²
  Represents all losses between pressure sensor and nozzle inlet
  Fluid: 0=Water, 1=ISOXEL_5450, 2=DFAB_3D
*)
CASE iFluid OF
  0: rAlpha := rAlpha_Water;
  1: rAlpha := rAlpha_ISOXEL;
  2: rAlpha := rAlpha_DFAB;
ELSE
  rAlpha := 0.0;
END_CASE;

GetAlpha := rAlpha;
